{
  "findings": [
    {
      "check_id": "CKV_GCP_7",
      "title": "Ensure Legacy Authorization is set to Disabled on Kubernetes Engine Clusters",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Legacy Authorization is enabled, which can lead to unintended access to cluster resources."
    },
    {
      "check_id": "CKV_GCP_13",
      "title": "Ensure client certificate authentication to Kubernetes Engine Clusters is disabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Client certificate authentication is enabled, which can be a security risk if not properly managed."
    },
    {
      "check_id": "CKV_GCP_12",
      "title": "Ensure Network Policy is enabled on Kubernetes Engine Clusters",
      "resource": "google_container_cluster.k8sexample",
      "severity": "CRITICAL",
      "explanation": "Network Policy is not enabled, which can lead to unrestricted communication between pods."
    },
    {
      "check_id": "CKV2_GCP_19",
      "title": "Ensure GCP Kubernetes engine clusters have 'alpha cluster' feature disabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The 'alpha cluster' feature is enabled, which can introduce unstable features into the cluster."
    }
  ],
  "patched_code": "resource \"google_container_cluster\" \"k8sexample\" {\n  name               = \"${var.vault_user}-k8s-cluster\"\n  description        = \"example k8s cluster\"\n  zone               = \"${var.gcp_zone}\"\n  initial_node_count = \"${var.initial_node_count}\"\n  enable_kubernetes_alpha = \"false\"\n  enable_legacy_abac = \"false\"\n  master_auth {\n    username = \"${var.master_username}\"\n    password = \"${var.master_password}\"\n    client_certificate_config {\n      issue_client_certificate = false\n    }\n  }\n  node_config {\n    machine_type = \"${var.node_machine_type}\"\n    disk_size_gb = \"${var.node_disk_size}\"\n    oauth_scopes = [\n      \"https://www.googleapis.com/auth/compute\",\n      \"https://www.googleapis.com/auth/devstorage.read_only\",\n      \"https://www.googleapis.com/auth/logging.write\",\n      \"https://www.googleapis.com/auth/monitoring\"\n    ]\n  }\n  network_policy {\n    enabled = true\n  }\n}",
  "fix_summary": "Disabled Legacy Authorization, client certificate authentication, and alpha cluster features. Enabled Network Policy to restrict pod communication."
}
